/* DAWAH X — ahmad, অধ্যায় 59 · খণ্ড 59 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][59]=[[11601,11601,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى لَا يُقَالَ فِي الْأَرْضِ اللَّهُ اللَّهُ ‏","","",""],[11602,11602,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسْأَلُونِي عَنْ شَيْءٍ إِلَى يَوْمِ الْقِيَامَةِ إِلَّا حَدَّثْتُكُمْ قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ حُذَافَةَ ‏ ‏يَا رَسُولَ اللَّهِ مَنْ أَبِي قَالَ أَبُوكَ ‏ ‏حُذَافَةُ ‏ ‏فَقَالَتْ أُمُّهُ مَا أَرَدْتَ إِلَى هَذَا قَالَ أَرَدْتُ أَنْ أَسْتَرِيحَ قَالَ وَكَانَ يُقَالُ فِيهِ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏وَأَحْسَبُ هَذَا عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِينَا بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا ‏ ‏وَبِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيًّا نَعُوذُ بِاللَّهِ مِنْ غَضِبِ اللَّهِ وَغَضِبِ رَسُولِهِ ‏","","",""],[11603,11603,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَيْرُ مَا تَدَاوَيْتُمْ بِهِ ‏ ‏الْحِجَامَةُ ‏ ‏وَالْقُسْطُ ‏ ‏الْبَحْرِيُّ وَلَا تُعَذِّبُوا صِبْيَانَكُمْ ‏ ‏بِالْغَمْزِ ‏","","",""],[11604,11604,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَإِذَا أَنَا بِقَصْرٍ مِنْ ذَهَبٍ فَقُلْتُ لِمَنْ هَذَا الْقَصْرُ قَالُوا لِشَابٍّ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قُلْتُ لِمَنْ قَالُوا ‏ ‏لِعُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ فَلَوْلَا مَا عَلِمْتُ مِنْ غَيْرَتِكَ لَدَخَلْتُهُ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏عَلَيْكَ يَا رَسُولَ اللَّهِ أَغَارُ ‏","","",""],[11605,11605,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ قُلْنَا يَا رَسُولَ اللَّهِ كُلُّنَا نَكْرَهُ الْمَوْتَ قَالَ لَيْسَ ذَاكَ كَرَاهِيَةَ الْمَوْتِ وَلَكِنَّ الْمُؤْمِنَ إِذَا حُضِرَ جَاءَهُ الْبَشِيرُ مِنْ اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ ‏ ‏صَائِرٌ ‏ ‏إِلَيْهِ فَلَيْسَ شَيْءٌ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَكُونَ قَدْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ فَأَحَبَّ اللَّهُ لِقَاءَهُ وَإِنَّ الْفَاجِرَ أَوْ الْكَافِرَ إِذَا حُضِرَ جَاءَهُ بِمَا هُوَ ‏ ‏صَائِرٌ ‏ ‏إِلَيْهِ مِنْ الشَّرِّ ‏ ‏أَوْ مَا يَلْقَاهُ مِنْ الشَّرِّ ‏ ‏فَكَرِهَ لِقَاءَ اللَّهِ وَكَرِهَ اللَّهُ لِقَاءَهُ ‏","","",""],[11606,11606,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏مَا مَسِسْتُ شَيْئًا قَطُّ خَزًّا وَلَا حَرِيرًا أَلْيَنَ مِنْ كَفِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا شَمَمْتُ رَائِحَةً أَطْيَبَ مِنْ رِيحِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11607,11607,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَادَ رَجُلًا مِنْ الْمُسْلِمِينَ قَدْ صَارَ مِثْلَ الْفَرْخِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ كُنْتَ تَدْعُو بِشَيْءٍ أَوْ تَسْأَلُهُ إِيَّاهُ قَالَ نَعَمْ كُنْتُ أَقُولُ اللَّهُمَّ مَا كُنْتَ مُعَاقِبِي بِهِ فِي الْآخِرَةِ فَعَجِّلْهُ لِي فِي الدُّنْيَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَانَ اللَّهِ لَا تُطِيقُهُ وَلَا تَسْتَطِيعُهُ فَهَلَّا قُلْتَ ‏ ‏اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ قَالَ فَدَعَا اللَّهَ عَزَّ وَجَلَّ فَشَفَاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[11608,11608,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ الرَّجُلُ يَأْتِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيُسْلِمُ لِشَيْءٍ ‏ ‏يُعْطَاهُ مِنْ الدُّنْيَا فَلَا يُمْسِي حَتَّى يَكُونَ الْإِسْلَامُ أَحَبَّ إِلَيْهِ وَأَعَزَّ عَلَيْهِ مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[11609,11609,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ يُسْأَلُ شَيْئًا عَلَى الْإِسْلَامِ إِلَّا أَعْطَاهُ قَالَ فَأَتَاهُ رَجُلٌ فَسَأَلَهُ فَأَمَرَ لَهُ بِشَاءٍ كَثِيرٍ بَيْنَ جَبَلَيْنِ مِنْ شَاءِ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ فَرَجَعَ إِلَى قَوْمِهِ فَقَالَ يَا قَوْمِ أَسْلِمُوا فَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْطِي عَطَاءً مَا ‏ ‏يَخْشَى ‏ ‏الْفَاقَةَ ‏","","",""],[11610,11610,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏بَعَثَتْ مَعِي ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏بِمِكْتَلٍ ‏ ‏فِيهِ رُطَبٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ أَجِدْهُ وَخَرَجَ قَرِيبًا إِلَى مَوْلًى لَهُ دَعَاهُ صَنَعَ لَهُ طَعَامًا قَالَ فَأَتَيْتُهُ فَإِذَا هُوَ يَأْكُلُ فَدَعَانِي لِآكُلَ مَعَهُ قَالَ وَصَنَعَ لَهُ ‏ ‏ثَرِيدًا ‏ ‏بِلَحْمٍ وَقَرْعٍ قَالَ ‏ ‏وَإِذَا هُوَ يُعْجِبُهُ الْقَرْعُ قَالَ فَجَعَلْتُ أَجْمَعُهُ ‏ ‏وَأُدْنِيهِ مِنْهُ قَالَ فَلَمَّا ‏ ‏طَعِمَ ‏ ‏رَجَعَ إِلَى مَنْزِلِهِ قَالَ وَوَضَعْتُ ‏ ‏الْمِكْتَلَ ‏ ‏بَيْنَ يَدَيْهِ قَالَ فَجَعَلَ يَأْكُلُ وَيَقْسِمُ حَتَّى فَرَغَ مِنْ آخِرِهِ ‏","","",""],[11611,11611,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فَأَتَتْهُ بِتَمْرٍ وَسَمْنٍ وَكَانَ صَائِمًا فَقَالَ ‏ ‏أَعِيدُوا تَمْرَكُمْ فِي وِعَائِهِ وَسَمْنَكُمْ فِي ‏ ‏سِقَائِهِ ‏ ‏ثُمَّ قَامَ إِلَى نَاحِيَةِ الْبَيْتِ فَصَلَّى رَكْعَتَيْنِ وَصَلَّيْنَا مَعَهُ ثُمَّ دَعَا ‏ ‏لِأُمِّ سُلَيْمٍ ‏ ‏وَلِأَهْلِهَا بِخَيْرٍ فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ لِي ‏ ‏خُوَيْصَّةً ‏ ‏قَالَ وَمَا هِيَ قَالَتْ خَادِمُكَ ‏ ‏أَنَسٌ ‏ ‏قَالَ فَمَا تَرَكَ خَيْرَ آخِرَةٍ وَلَا دُنْيَا إِلَّا دَعَا لِي بِهِ وَقَالَ اللَّهُمَّ ارْزُقْهُ مَالًا وَوَلَدًا وَبَارِكْ لَهُ فِيهِ قَالَ فَمَا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِنْسَانٌ أَكْثَرُ مِنِّي مَالًا وَذَكَرَ أَنَّهُ لَا يَمْلِكُ ذَهَبًا وَلَا فِضَّةً غَيْرَ خَاتَمِهِ قَالَ وَذَكَرَ أَنَّ ابْنَتَهُ الْكُبْرَى ‏ ‏أُمَيْنَةَ ‏ ‏أَخْبَرَتْهُ أَنَّهُ دُفِنَ مِنْ ‏ ‏صُلْبِهِ ‏ ‏إِلَى مَقْدَمِ ‏ ‏الْحَجَّاجِ ‏ ‏نَيِّفًا عَلَى عِشْرِينَ وَمِائَةٍ ‏","","",""],[11612,11612,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏هَلْ ‏ ‏خَضَبَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّهُ لَمْ يَرَ مِنْ الشَّيْبِ إِلَّا نَحْوًا مِنْ سَبْعَ عَشْرَةَ أَوْ عِشْرِينَ شَعْرَةً فِي مُقَدَّمِ لِحْيَتِهِ وَقَالَ إِنَّهُ لَمْ يَشِنْ بِالشَّيْبِ ‏ ‏فَقِيلَ ‏ ‏لِأَنَسٍ ‏ ‏أَشَيْنٌ هُوَ قَالَ كُلُّكُمْ يَكْرَهُهُ وَلَكِنْ ‏ ‏خَضَبَ ‏ ‏أَبُو بَكْرٍ ‏ ‏بِالْحِنَّاءِ وَالْكَتَمِ ‏ ‏وَخَضَبَ ‏ ‏عُمَرُ ‏ ‏بِالْحِنَّاءِ ‏","","",""],[11613,11613,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ فَاطَّلَعَ إِلَيْهِ ‏ ‏رَجُلٌ ‏ ‏فَأَهْوَى ‏ ‏إِلَيْهِ ‏ ‏بِمِشْقَصٍ ‏ ‏مَعَهُ ‏ ‏فَتَأَخَّرَ ‏ ‏الرَّجُلُ ‏","","",""],[11614,11614,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا مُوسَى ‏ ‏اسْتَحْمَلَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَافَقَ مِنْهُ شُغْلًا فَقَالَ وَاللَّهِ لَا أَحْمِلُكَ فَلَمَّا ‏ ‏قَفَّى ‏ ‏دَعَاهُ ‏ ‏فَحَمَلَهُ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّكَ حَلَفْتَ أَنْ تَحْمِلَنِي قَالَ ‏ ‏فَأَنَا أَحْلِفُ لَأَحْمِلَنَّكَ ‏","","",""],[11615,11615,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ سَلَامٍ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْدَمَهُ ‏ ‏الْمَدِينَةَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي سَائِلُكَ عَنْ ثَلَاثِ خِصَالٍ لَا يَعْلَمُهُنَّ إِلَّا نَبِيٌّ قَالَ سَلْ قَالَ مَا أَوَّلُ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ وَمَا أَوَّلُ مَا يَأْكُلُ مِنْهُ أَهْلُ الْجَنَّةِ وَمِنْ أَيْنَ يُشْبِهُ الْوَلَدُ أَبَاهُ وَأُمَّهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَنِي بِهِنَّ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏آنِفًا قَالَ ذَلِكَ عَدُوُّ ‏ ‏الْيَهُودِ ‏ ‏مِنْ الْمَلَائِكَةِ قَالَ أَمَّا أَوَّلُ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ ‏ ‏فَنَارٌ تَخْرُجُ مِنْ الْمَشْرِقِ فَتَحْشُرُ النَّاسَ إِلَى الْمَغْرِبِ وَأَمَّا أَوَّلُ مَا يَأْكُلُ مِنْهُ أَهْلُ الْجَنَّةِ زِيَادَةُ كَبِدِ حُوتٍ وَأَمَّا شَبَهُ الْوَلَدِ أَبَاهُ وَأُمَّهُ فَإِذَا سَبَقَ مَاءُ الرَّجُلِ مَاءَ الْمَرْأَةِ ‏ ‏نَزَعَ ‏ ‏إِلَيْهِ الْوَلَدُ وَإِذَا سَبَقَ ‏ ‏مَاءُ ‏ ‏الْمَرْأَةِ ‏ ‏مَاءَ ‏ ‏الرَّجُلِ ‏ ‏نَزَعَ ‏ ‏إِلَيْهَا قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّكَ رَسُولُ اللَّهِ وَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏الْيَهُودَ ‏ ‏قَوْمٌ ‏ ‏بُهْتٌ ‏ ‏وَإِنَّهُمْ إِنْ يَعْلَمُوا بِإِسْلَامِي يَبْهَتُونِي عِنْدَكَ فَأَرْسِلْ إِلَيْهِمْ فَاسْأَلْهُمْ عَنِّي أَيُّ رَجُلٍ ‏ ‏ابْنُ سَلَامٍ ‏ ‏فِيكُمْ قَالَ فَأَرْسَلَ إِلَيْهِمْ فَقَالَ أَيُّ رَجُلٍ ‏ ‏عَبْدُ اللَّهِ بْنُ سَلَامٍ ‏ ‏فِيكُمْ قَالُوا خَيْرُنَا وَابْنُ خَيْرِنَا وَعَالِمُنَا وَابْنُ عَالِمِنَا وَأَفْقَهُنَا وَابْنُ أَفْقَهِنَا قَالَ أَرَأَيْتُمْ إِنْ أَسْلَمَ تُسْلِمُونَ قَالُوا أَعَاذَهُ اللَّهُ مِنْ ذَلِكَ قَالَ فَخَرَجَ ‏ ‏ابْنُ سَلَامٍ ‏ ‏فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قَالُوا شَرُّنَا وَابْنُ شَرِّنَا وَجَاهِلُنَا وَابْنُ جَاهِلِنَا فَقَالَ ‏ ‏ابْنُ سَلَامٍ ‏ ‏هَذَا الَّذِي كُنْتُ أَتَخَوَّفُ مِنْهُ ‏","","",""],[11616,11616,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا انْهَزَمَ الْمُسْلِمُونَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏نَادَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏يَا رَسُولَ اللَّهِ اقْتُلْ مَنْ بَعْدَنَا انْهَزَمُوا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ كَفَى قَالَ فَأَتَاهَا ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَمَعَهَا ‏ ‏مِعْوَلٌ ‏ ‏فَقَالَ مَا هَذَا يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ إِنْ دَنَا مِنِّي أَحَدٌ مِنْ الْمُشْرِكِينَ بَعَجْتُهُ قَالَ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَسُولَ اللَّهِ انْظُرْ مَا تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَرَدْتُ أَنْ أُسْلِمَ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي سَائِلُكَ فَقَالَ سَلْ عَمَّا بَدَا لَكَ قَالَ قُلْتُ مَا أَوَّلُ مَا يَأْكُلُ أَهْلُ الْجَنَّةِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[11617,11617,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَلْعَبُ مَعَ الْغِلْمَانِ فَأَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي حَدِيثِهِ عَلَيْنَا ‏ ‏وَأَخَذَ بِيَدِي ‏ ‏فَبَعَثَنِي فِي حَاجَةٍ وَقَعَدَ فِي ظِلِّ ‏ ‏حَائِطٍ ‏ ‏أَوْ جِدَارٍ حَتَّى رَجَعْتُ إِلَيْهِ فَبَلَّغْتُ الرِّسَالَةَ الَّتِي بَعَثَنِي فِيهَا فَلَمَّا أَتَيْتُ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ مَا حَبَسَكَ قُلْتُ بَعَثَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَاجَةٍ لَهُ قَالَتْ وَمَا هِيَ قُلْتُ سِرٌّ قَالَتْ احْفَظْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِرَّهُ قَالَ فَمَا حَدَّثْتُ بِهِ أَحَدًا بَعْدُ ‏","","",""],[11618,11618,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ أَسْلِمْ قَالَ أَجِدُنِي كَارِهًا قَالَ ‏ ‏أَسْلِمْ وَإِنْ كُنْتَ كَارِهًا ‏","","",""],[11619,11619,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏النُّخَاعَةُ ‏ ‏فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا ‏","","",""],[11620,11620,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي الصَّلَاةِ فَإِنَّهُ مُنَاجٍ رَبَّهُ فَلَا يَتْفُلَنَّ أَحَدٌ مِنْكُمْ عَنْ يَمِينِهِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَلَا ‏ ‏يَتْفُلُ ‏ ‏أَمَامَهُ وَلَا عَنْ يَمِينِهِ ‏ ‏وَلَكِنْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمَيْهِ ‏","","",""],[11621,11621,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏أَتَاهُ ‏ ‏رِعْلٌ ‏ ‏وَذَكْوَانُ ‏ ‏وَعُصَيَّةُ ‏ ‏وَبَنُو لِحْيَانَ ‏ ‏فَزَعَمُوا أَنَّهُمْ قَدْ أَسْلَمُوا فَاسْتَمَدُّوهُ عَلَى قَوْمِهِمْ فَأَمَدَّهُمْ نَبِيُّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏يَوْمَئِذٍ بِسَبْعِينَ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏كُنَّا نُسَمِّيهِمْ فِي زَمَانِهِمْ الْقُرَّاءَ كَانُوا يَحْطِبُونَ بِالنَّهَارِ وَيُصَلُّونَ بِاللَّيْلِ فَانْطَلَقُوا بِهِمْ حَتَّى إِذَا أَتَوْا ‏ ‏بِئْرَ مَعُونَةَ ‏ ‏غَدَرُوا بِهِمْ فَقَتَلُوهُمْ ‏ ‏فَقَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا فِي صَلَاةِ الصُّبْحِ يَدْعُو عَلَى هَذِهِ الْأَحْيَاءِ ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏قَالَ قَالَ ‏ ‏قَتَادَةُ ‏ ‏وَحَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏أَنَّهُمْ قَرَءُوا بِهِ قُرْآنًا ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ إِنَّا قَرَأْنَا بِهِمْ قُرْآنًا ‏ ‏بَلِّغُوا عَنَّا قَوْمَنَا وَإِنَّا قَدْ لَقِينَا رَبَّنَا فَرَضِيَ عَنَّا وَأَرْضَانَا ثُمَّ رُفِعَ ذَلِكَ بَعْدُ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ثُمَّ ‏ ‏نُسِخَ ‏ ‏ذَلِكَ ‏ ‏أَوْ رُفِعَ ‏","","",""],[11622,11622,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَالْخَفَّافُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي صَلَاتِهِمْ وَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11623,11623,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏وَعَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا ‏ ‏يَفْتَرِشْ ‏ ‏أَحَدُكُمْ ذِرَاعَيْهِ كَالْكَلْبِ ‏","","",""],[11624,11624,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏وَعَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَدْخُلُ الصَّلَاةَ وَأَنَا أُرِيدُ أَنْ أُطِيلَهَا فَأَسْمَعُ بُكَاءَ الصَّبِيِّ فَأَتَجَاوَزُ فِي صَلَاتِي مِمَّا أَعْلَمُ مِنْ شِدَّةِ ‏ ‏وَجْدِ ‏ ‏أُمِّهِ مِنْ بُكَائِهِ ‏","","",""],[11625,11625,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ يَوْمَ الْفَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَعَلَيْهِ ‏ ‏الْمِغْفَرُ ‏ ‏فَقِيلَ لَهُ إِنَّ ‏ ‏ابْنَ خَطَلٍ ‏ ‏مُتَعَلِّقٌ بِأَسْتَارِ ‏ ‏الْكَعْبَةِ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَفِيمَا ‏ ‏قَرَأْتُ عَلَيْهِ ‏ ‏يَعْنِي ‏ ‏مَالِكٍ ‏ ‏قَالَ ‏ ‏وَلَمْ يَكُنْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ مُحْرِمًا وَاللَّهُ أَعْلَمُ ‏","","",""],[11626,11626,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏كَيْفَ كُنْتُمْ تَصْنَعُونَ فِي هَذَا الْيَوْمِ ‏ ‏يَعْنِي يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ ‏ ‏الْمُهِلُّ ‏ ‏مِنَّا فَلَا يُنْكِرُ عَلَيْهِ وَيُكَبِّرُ الْمُكَبِّرُ مِنَّا فَلَا يُنْكِرُ عَلَيْهِ ‏","","",""],[11627,11627,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لَا يَقْطَعُهَا ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ بِهِ ‏","","",""],[11628,11628,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَأَنْ ‏ ‏يُنْبَذَ ‏ ‏فِيهِ ‏","","",""],[11629,11629,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏آخِرُ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الِاثْنَيْنِ كَشَفَ السِّتَارَةَ وَالنَّاسُ خَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَنَظَرْتُ إِلَى وَجْهِهِ كَأَنَّهُ وَرَقَةُ مُصْحَفٍ فَأَرَادَ النَّاسُ أَنْ يَتَحَرَّكُوا فَأَشَارَ إِلَيْهِمْ أَنْ اثْبُتُوا وَيَلْقَى ‏ ‏السَّجْفَ ‏ ‏وَتُوُفِّيَ فِي آخِرِ ذَلِكَ الْيَوْمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[11630,11630,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقَاطَعُوا وَلَا تَبَاغَضُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ ‏","","",""],[11631,11631,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَقَطَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ فَرَسٍ ‏ ‏فَجُحِشَ ‏ ‏شِقُّهُ ‏ ‏الْأَيْمَنُ فَدَخَلْنَا عَلَيْهِ نَعُودُهُ فَحَضَرَتْ الصَّلَاةُ فَصَلَّى قَاعِدًا وَصَلَّيْنَا قُعُودًا فَلَمَّا قَضَى الصَّلَاةَ قَالَ ‏ ‏إِنَّمَا الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا رَكَعَ فَارْكَعُوا ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً فَإِذَا سَجَدَ فَاسْجُدُوا ‏ ‏وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا أَجْمَعُونَ ‏","","",""],[11632,11632,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ السَّاعَةِ فَقَالَ مَا أَعْدَدْتَ لَهَا قَالَ مَا أَعْدَدْتُ لَهَا مِنْ شَيْءٍ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً مَا أَعْدَدْتُ لَهَا كَثِيرَ شَيْءٍ ‏ ‏وَلَكِنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ ‏ ‏الْمَرْءُ مَعَ مَنْ أَحَبَّ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أُخْرَى أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[11633,11633,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏وُضِعَ ‏ ‏الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[11634,11634,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَأَنَا ابْنُ عَشْرٍ وَمَاتَ وَأَنَا ابْنُ عِشْرِينَ وَكُنَّ ‏ ‏أُمَّهَاتِي تَحُثُّنِي عَلَى خِدْمَتِهِ فَدَخَلَ عَلَيْنَا فَحَلَبْنَا لَهُ مِنْ شَاةٍ ‏ ‏دَاجِنٍ ‏ ‏وَشِيبَ ‏ ‏لَهُ مِنْ بِئْرٍ فِي الدَّارِ وَأَعْرَابِيٌّ عَنْ يَمِينِهِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏عَنْ يَسَارِهِ ‏ ‏وَعُمَرُ ‏ ‏نَاحِيَةً فَشَرِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَعْطِ ‏ ‏أَبَا بَكْرٍ ‏ ‏فَنَاوَلَ الْأَعْرَابِيَّ وَقَالَ الْأَيْمَنُ فَالْأَيْمَنُ ‏ ‏و قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً ‏ ‏الزُّهْرِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَسٌ ‏","","",""],[11635,11635,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْلَمَ ‏ ‏عَلَى ‏ ‏صَفِيَّةَ ‏ ‏بِتَمْرٍ وَسَوِيقٍ ‏","","",""],[11636,11636,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ مَيْسَرَةَ ‏ ‏وحَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُنْكَدِرِ ‏ ‏سَمِعْتُهُمَا يَقُولَانِ سَمِعْنَا ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا ‏ ‏وَبِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[11637,11637,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَتْبَعُ الْمَيِّتَ ثَلَاثٌ أَهْلُهُ وَمَالُهُ وَعَمَلُهُ فَيَرْجِعُ اثْنَانِ وَيَبْقَى وَاحِدٌ أَهْلُهُ وَمَالُهُ وَيَبْقَى عَمَلُهُ ‏","","",""],[11638,11638,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ أَنَا وَيَتِيمٌ كَانَ عِنْدَنَا فِي الْبَيْتِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً فِي بَيْتِنَا ‏ ‏خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَتَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي دَارِهِمْ وَصَلَّتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏خَلْفَنَا ‏","","",""],[11639,11639,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَهْرِيقُوا ‏ ‏عَلَيْهِ ‏ ‏ذَنُوبًا ‏ ‏أَوْ ‏ ‏سَجْلًا ‏ ‏مِنْ ‏ ‏مَاءٍ ‏","","",""],[11640,11640,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا وَالْعَصْرَ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[11641,11641,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏فَكَانُوا يَفْتَتِحُونَ ‏ ‏بِ ‏ { ‏الْحَمْدُ ‏}","","",""],[11642,11642,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏يَعْنِي ‏ ‏سَمِعَ مِنْ ‏ ‏أَنَسٍ ‏ ‏يَقُولُ ‏ ‏دَعَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَنْصَارَ ‏ ‏لِيُقْطِعَ لَهُمْ ‏ ‏الْبَحْرَيْنِ ‏ ‏فَقَالُوا لَا حَتَّى تُقْطِعَ لِإِخْوَانِنَا مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏مِثْلَنَا فَقَالَ ‏ ‏إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي ‏","","",""],[11643,11643,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَبَّحَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏بُكْرَةً ‏ ‏وَقَدْ خَرَجُوا ‏ ‏بِالْمَسَاحِي ‏ ‏فَلَمَّا نَظَرُوا إِلَيْهِ قَالُوا ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏ثُمَّ أَحَالُوا يَسْعَوْنَ إِلَى الْحِصْنِ وَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَيْهِ ثُمَّ كَبَّرَ ثَلَاثًا ثُمَّ قَالَ ‏ ‏خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ فَأَصَبْنَا حُمُرًا خَارِجَةً مِنْ الْقَرْيَةِ فَاطَّبَخْنَاهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْ الْحُمُرِ الْأَهْلِيَّةِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏ ‏مِنْ عَمَلِ الشَّيْطَانِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مُحَمَّدٌ ‏ ‏وَالْخَمِيسُ ‏ ‏يَقُولُ وَالْجَيْشُ ‏","","",""],[11644,11644,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَا وَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏سَرِيَّةٍ ‏ ‏مَا وَجَدَ عَلَيْهِمْ كَانُوا يُسَمَّوْنَ الْقُرَّاءَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏نَزَلَ فِيهِمْ بَلِّغُوا قَوْمَنَا عَنَّا أَنَّا قَدْ رَضِينَا وَرَضِيَ عَنَّا قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏فِيمَنْ نَزَلَتْ قَالَ فِي أَهْلِ ‏ ‏بِئْرِ مَعُونَةَ ‏","","",""],[11645,11645,"","","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏عَاصِمًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏مَا وَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ مَا وَجَدَ عَلَى السَّبْعِينَ الَّذِينَ أُصِيبُوا ‏ ‏بِبِئْرِ مَعُونَةَ ‏","","",""],[11646,11646,"","","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏عَاصِمًا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏حَالَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏فِي دَارِنَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَأَنَّهُ يَقُولُ آخَى ‏","","",""],[11647,11647,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ وَكَانَ لَهُ ‏ ‏حَادٍ ‏ ‏يُقَالُ لَهُ ‏ ‏أَنْجَشَةُ ‏ ‏وَكَانَتْ ‏ ‏أُمُّ أَنَسٍ ‏ ‏مَعَهُمْ فَقَالَ يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[11648,11648,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي ‏ ‏بِالْبَيْدَاءِ ‏ ‏لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ مَعًا ‏","","",""],[11649,11649,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَابْنُ سِيرِينَ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏رَمَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمْرَةَ الْعَقَبَةِ ‏ ‏وَنَحَرَ هَدْيَهُ ‏ ‏حَجَمَ ‏ ‏وَأَعْطَى ‏ ‏الْحَجَّامَ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً وَأَعْطَى الْحَالِقَ ‏ ‏شِقَّهُ ‏ ‏الْأَيْمَنَ فَحَلَقَهُ فَأَعْطَاهُ ‏ ‏أَبَا طَلْحَةَ ‏ ‏ثُمَّ حَلَقَ الْأَيْسَرَ فَأَعْطَاهُ النَّاسَ ‏","","",""],[11650,11650,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَهْدَى ‏ ‏أُكَيْدِرُ ‏ ‏دُومَةَ ‏ ‏لِلنَّبِيِّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏يَعْنِي حُلَّةً ‏ ‏فَأَعْجَبَ النَّاسَ حُسْنُهَا فَقَالَ ‏ ‏لَمَنَادِيلُ ‏ ‏سَعْدٍ ‏ ‏فِي الْجَنَّةِ خَيْرٌ ‏ ‏أَوْ أَحْسَنُ ‏ ‏مِنْهَا ‏","","",""],[11651,11651,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏قَالَ قَالَ ‏ ‏ثَابِتٌ ‏ ‏لِأَنَسٍ ‏ ‏يَا ‏ ‏أَنَسُ ‏ ‏مَسِسْتَ يَدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِكَ قَالَ نَعَمْ قَالَ أَرِنِي أُقَبِّلُهَا ‏","","",""],[11652,11652,"","","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ مِنِ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَصَوْتُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فِي الْجَيْشِ خَيْرٌ مِنْ فِئَةٍ ‏","","",""],[11653,11653,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعَ ‏ ‏قَاسِمٌ الرَّحَّالُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏خَرِبًا ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏وَكَانَ يَقْضِي فِيهَا حَاجَةً فَخَرَجَ إِلَيْنَا مَذْعُورًا ‏ ‏أَوْ فَزِعًا ‏ ‏وَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَسَأَلْتُ اللَّهَ تَبَارَكَ وَتَعَالَى أَنْ يُسْمِعَكُمْ مِنْ عَذَابِ أَهْلِ الْقُبُورِ مَا أَسْمَعَنِي ‏","","",""],[11654,11654,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُطِيفُ ‏ ‏بِنِسَائِهِ فِي لَيْلَةٍ يَغْتَسِلُ غُسْلًا وَاحِدًا ‏","","",""],[11655,11655,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ مَيْسَرَةَ ‏ ‏وَمُحَمَّدَ بْنَ الْمُنْكَدِرِ ‏ ‏يَقُولَانِ سَمِعْنَا ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْمَدِينَةِ ‏ ‏أَرْبَعًا ‏ ‏وَبِذِي الْحُلَيْفَةِ ‏ ‏رَكْعَتَيْنِ ‏","","",""],[11656,11656,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُخْتَارَ بْنَ فُلْفُلٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ الشُّرْبِ فِي الْأَوْعِيَةِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُزَفَّتَةِ ‏ ‏وَقَالَ كُلُّ مُسْكِرٍ حَرَامٌ ‏ ‏قَالَ ‏ ‏قُلْتُ وَمَا ‏ ‏الْمُزَفَّتَةُ ‏ ‏قَالَ ‏ ‏الْمُقَيَّرَةُ ‏ ‏قَالَ قُلْتُ فَالرَّصَاصُ وَالْقَارُورَةُ قَالَ مَا ‏ ‏بَأْسٌ ‏ ‏بِهِمَا قَالَ قُلْتُ فَإِنَّ نَاسًا يَكْرَهُونَهُمَا قَالَ دَعْ مَا ‏ ‏يَرِيبُكَ ‏ ‏إِلَى مَا لَا ‏ ‏يَرِيبُكَ ‏ ‏فَإِنَّ كُلَّ مُسْكِرٍ حَرَامٌ قَالَ قُلْتُ لَهُ صَدَقْتَ السُّكْرُ حَرَامٌ فَالشَّرْبَةُ وَالشَّرْبَتَانِ عَلَى طَعَامِنَا قَالَ مَا أَسْكَرَ كَثِيرُهُ فَقَلِيلُهُ حَرَامٌ وَقَالَ الْخَمْرُ مِنْ الْعِنَبِ وَالتَّمْرِ وَالْعَسَلِ ‏ ‏وَالْحِنْطَةِ ‏ ‏وَالشَّعِيرِ وَالذُّرَةِ فَمَا خَمَّرْتَ مِنْ ذَلِكَ فَهِيَ الْخَمْرُ ‏","","",""],[11657,11657,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَبَرَّزَ لِحَاجَتِهِ أَتَيْتُهُ بِمَاءٍ فَيَغْسِلُ بِهِ ‏","","",""],[11658,11658,"","","‏ ‏قَالَ ‏ ‏قُرِئَ عَلَى ‏ ‏سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ جُدْعَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَصَوْتُ ‏ ‏أَبِي طَلْحَةَ ‏ ‏فِي الْجَيْشِ خَيْرٌ مِنْ فِئَةٍ ‏","","",""],[11659,11659,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ أَحَدًا كَانَ أَرْحَمَ بِالْعِيَالِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِبْرَاهِيمُ ‏ ‏مُسْتَرْضَعًا فِي ‏ ‏عَوَالِي ‏ ‏الْمَدِينَةِ ‏ ‏وَكَانَ يَنْطَلِقُ وَنَحْنُ مَعَهُ فَيَدْخُلُ الْبَيْتَ وَإِنَّهُ لَيُدَّخَنُ وَكَانَ ‏ ‏ظِئْرُهُ ‏ ‏قَيْنًا فَيَأْخُذُهُ فَيُقَبِّلُهُ ثُمَّ يَرْجِعُ قَالَ ‏ ‏عَمْرٌو ‏ ‏فَلَمَّا تُوُفِّيَ ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏ابْنِي وَإِنَّهُ مَاتَ فِي الثَّدْيِ فَإِنَّ لَهُ ‏ ‏ظِئْرَيْنِ ‏ ‏يُكْمِلَانِ رَضَاعَهُ فِي الْجَنَّةِ ‏","","",""],[11660,11660,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ الْمُنْذِرِ بْنِ الْجَارُودِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَنَعَ بَعْضُ عُمُومَتِي لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامًا فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أُحِبُّ أَنْ تَأْكُلَ فِي بَيْتِي وَتُصَلِّيَ فِيهِ قَالَ فَأَتَاهُ وَفِي الْبَيْتِ ‏ ‏فَحْلٌ ‏ ‏مِنْ تِلْكَ الْفُحُولِ ‏ ‏فَأَمَرَ بِجَانِبٍ مِنْهُ فَكُنِسَ وَرُشَّ فَصَلَّى وَصَلَّيْنَا مَعَهُ ‏","","",""],[11661,11661,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ فِي صَلَاتِهِمْ فَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11662,11662,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَرْأَةُ مِنْ نِسَائِهِ يَغْتَسِلَانِ مِنْ إِنَاءٍ وَاحِدٍ وَكَانَ يَغْتَسِلُ بِخَمْسِ ‏ ‏مَكَاكِيَّ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏","","",""],[11663,11663,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَعِدَ ‏ ‏أُحُدًا ‏ ‏فَتَبِعَهُ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏فَرَجَفَ بِهِمْ الْجَبَلُ فَقَالَ ‏ ‏اسْكُنْ عَلَيْكَ نَبِيٌّ وَصِدِّيقٌ وَشَهِيدَانِ ‏","","",""],[11664,11664,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ ‏ ‏يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ آمَنَّا بِكَ وَبِمَا جِئْتَ بِهِ فَهَلْ تَخَافُ عَلَيْنَا قَالَ فَقَالَ نَعَمْ إِنَّ الْقُلُوبَ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّهِ عَزَّ وَجَلَّ يُقَلِّبُهَا ‏","","",""],[11665,11665,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏يُضْحِكُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ أَلَمْ تَرَ إِلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏مَعَهَا خِنْجَرٌ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَصْنَعِينَ بِهِ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ أَرَدْتُ إِنْ ‏ ‏دَنَا ‏ ‏مِنِّي أَحَدٌ مِنْهُمْ طَعَنْتُهُ بِهِ ‏","","",""],[11666,11666,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏قَالَ ‏ ‏قُلْنَا ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏مَا ‏ ‏أَنْكَرْتَ ‏ ‏مِنْ حَالِنَا فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنْكَرْتُ أَنَّكُمْ لَا تُقِيمُونَ الصُّفُوفَ ‏","","",""],[11667,11667,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[11668,11668,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مِسْحَاجٌ الضَّبِّيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قَالَ كُنَّا إِذَا كُنَّا مَعَ النَّبِيِّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏فِي سَفَرٍ فَقُلْنَا ‏ ‏زَالَتْ الشَّمْسُ أَوْ لَمْ تَزُلْ صَلَّى الظُّهْرَ ثُمَّ ارْتَحَلَ ‏","","",""],[11669,11669,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏جِبْرِيلُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ وَهُوَ جَالِسٌ ‏ ‏حَزِينٌ ‏ ‏قَدْ ‏ ‏خُضِبَ ‏ ‏بِالدِّمَاءِ ضَرَبَهُ بَعْضُ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَالَ فَقَالَ لَهُ وَمَا لَكَ قَالَ فَقَالَ لَهُ فَعَلَ بِي هَؤُلَاءِ وَفَعَلُوا قَالَ فَقَالَ لَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتُحِبُّ أَنْ أُرِيَكَ ‏ ‏آيَةً ‏ ‏قَالَ نَعَمْ قَالَ فَنَظَرَ إِلَى شَجَرَةٍ مِنْ وَرَاءِ ‏ ‏الْوَادِي ‏ ‏فَقَالَ ادْعُ بِتِلْكَ الشَّجَرَةِ فَدَعَاهَا فَجَاءَتْ تَمْشِي حَتَّى قَامَتْ بَيْنَ يَدَيْهِ فَقَالَ مُرْهَا فَلْتَرْجِعْ فَأَمَرَهَا فَرَجَعَتْ إِلَى مَكَانِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَسْبِي ‏","","",""],[11670,11670,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْبُخْلِ وَعَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ‏","","",""],[11671,11671,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَخَذَ ‏ ‏الرَّايَةَ ‏ ‏زَيْدٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏جَعْفَرٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَأُصِيبَ وَإِنَّ عَيْنَيْهِ لَتَذْرِفَانِ ثُمَّ أَخَذَهَا ‏ ‏خَالِدٌ ‏ ‏مِنْ غَيْرِ ‏ ‏إِمْرَةٍ ‏ ‏فَفَتَحَ اللَّهُ عَلَيْهِ وَمَا يَسُرُّنِي أَنَّهُمْ عِنْدَنَا ‏ ‏أَوْ قَالَ مَا يَسُرُّهُمْ أَنَّهُمْ عِنْدَنَا ‏","","",""],[11672,11672,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ابْنُ عُلَيَّةَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ زَاذَوَيْهِ ‏ ‏قَالَ قَالَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏نُهِينَا ‏ ‏أَوْ قَالَ أُمِرْنَا ‏ ‏أَنْ لَا نَزِيدَ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏عَلَى وَعَلَيْكُمْ ‏","","",""],[11673,11673,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَقَارِبَةً وَصَلَاةُ ‏ ‏أَبِي بَكْرٍ ‏ ‏حَتَّى مَدَّ ‏ ‏عُمَرُ ‏ ‏فِي صَلَاةِ الْفَجْرِ ‏","","",""],[11674,11674,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏هَلْ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَعَمْ بَعْدَ الرُّكُوعِ ثُمَّ سُئِلَ بَعْدَ ذَلِكَ مَرَّةً أُخْرَى هَلْ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَاةِ الصُّبْحِ قَالَ نَعَمْ بَعْدَ الرُّكُوعِ يَسِيرًا ‏","","",""],[11675,11675,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ شَعْرُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَنْصَافِ أُذُنَيْهِ ‏","","",""],[11676,11676,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ وَقْتِ صَلَاةِ الصُّبْحِ قَالَ ‏ ‏فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏حِينَ طَلَعَ الْفَجْرُ فَأَقَامَ الصَّلَاةَ ثُمَّ أَسْفَرَ مِنْ الْغَدِ حَتَّى ‏ ‏أَسْفَرَ ‏ ‏ثُمَّ قَالَ أَيْنَ السَّائِلُ عَنْ وَقْتِ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏مَا بَيْنَ هَاتَيْنِ ‏ ‏أَوْ قَالَ هَذَيْنِ ‏ ‏وَقْتٌ ‏","","",""],[11677,11677,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏النَّحْرِ ‏ ‏مَنْ كَانَ ذَبَحَ قَبْلَ الصَّلَاةِ فَلْيُعِدْ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ هَذَا يَوْمٌ ‏ ‏يُشْتَهَى فِيهِ اللَّحْمُ وَذَكَرَ ‏ ‏هَنَةً ‏ ‏مِنْ جِيرَانِهِ فَكَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَّقَهُ قَالَ وَعِنْدِي ‏ ‏جَذَعَةٌ ‏ ‏هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ قَالَ فَرَخَّصَ لَهُ فَلَا أَدْرِي بَلَغَتْ رُخْصَتُهُ مَنْ سِوَاهُ أَمْ لَا قَالَ ثُمَّ ‏ ‏انْكَفَأَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏إِلَى كَبْشَيْنِ فَذَبَحَهُمَا وَقَامَ النَّاسُ إِلَى ‏ ‏غُنَيْمَةٍ ‏ ‏فَتَوَزَّعُوهَا ‏ ‏أَوْ قَالَ فَتَجَزَّعُوهَا هَكَذَا قَالَ ‏ ‏أَيُّوبُ ‏","","",""],[11678,11678,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏شَرِبَ وَعَنْ يَمِينِهِ أَعْرَابِيٌّ وَعَنْ يَسَارِهِ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَنَاوَلَهُ وَقَالَ ‏ ‏الْأَيْمَنَ فَالْأَيْمَنَ ‏","","",""],[11679,11679,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَوْفَلِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَقُلْنَا حَدِّثْنَا بِمَا سَمِعْتَ مِنْ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ثَلَاثٌ مَنْ كُنَّ فِيهِ حُرِّمَ عَلَى النَّارِ وَحُرِّمَتْ النَّارُ عَلَيْهِ ‏ ‏إِيمَانٌ بِاللَّهِ وَحُبُّ اللَّهِ وَأَنْ يُلْقَى فِي النَّارِ فَيُحْرَقَ أَحَبُّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ فِي الْكُفْرِ ‏","","",""],[11680,11680,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحَائِطٍ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏فَسَمِعَ صَوْتًا مِنْ قَبْرٍ فَقَالَ مَتَى مَاتَ صَاحِبُ هَذَا الْقَبْرِ قَالُوا مَاتَ فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[11681,11681,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عُبَيْدٍ الطَّائِيِّ ‏ ‏حَدَّثَنِي ‏ ‏بُشَيْرُ بْنُ يَسَارٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَنَسٌ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَقُلْنَا لَهُ مَا أَنْكَرْتَ مِنَّا مِنْ عَهْدِ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا أَنْكَرْتُ مِنْكُمْ شَيْئًا غَيْرَ أَنَّكُمْ لَا تُقِيمُونَ صُفُوفَكُمْ ‏","","",""],[11682,11682,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَرَكَةُ فِي ‏ ‏نَوَاصِي ‏ ‏الْخَيْلِ ‏","","",""],[11683,11683,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْمَعُوا وَأَطِيعُوا وَإِنْ اسْتُعْمِلَ عَلَيْكُمْ حَبَشِيٌّ كَأَنَّ رَأْسَهُ زَبِيبَةٌ ‏","","",""],[11684,11684,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِرَجُلٍ وَهُوَ ‏ ‏يُهَادَى ‏ ‏بَيْنَ ابْنَيْهِ قَالُوا نَذَرَ أَنْ يَمْشِيَ قَالَ ‏ ‏إِنَّ اللَّهَ لَغَنِيٌّ عَنْ تَعْذِيبِ هَذَا لِنَفْسِهِ فَأَمَرَهُ أَنْ يَرْكَبَ ‏","","",""],[11685,11685,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَجِيٌّ ‏ ‏لِرَجُلٍ حَتَّى نَعَسَ أَوْ كَادَ يَنْعَسُ بَعْضُ الْقَوْمِ ‏","","",""],[11686,11686,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ صَلَاةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَ ‏ ‏مَا كُنَّا نَشَاءُ أَنْ ‏ ‏نَرَاهُ مُصَلِّيًا إِلَّا رَأَيْنَاهُ وَلَا نَائِمًا إِلَّا رَأَيْنَاهُ ‏","","",""],[11687,11687,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَنَادَى رَجُلٌ يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَالْتَفَتَ إِلَيْهِ فَقَالَ لَمْ أَعْنِكَ قَالَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏","","",""],[11688,11688,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَمَّادٍ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏مَنْ قَتَلَ كَافِرًا فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏قَالَ ‏ ‏فَقَتَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏عِشْرِينَ ‏","","",""],[11689,11689,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدِ بْنِ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ يَعْنِي الْأَنْصَارِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏دَخَلَ أَعْرَابِيٌّ الْمَسْجِدَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَالَ فَنَهَوْهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهُ وَأَمَرَ أَنْ يُصَبَّ عَلَيْهِ ‏ ‏أَوْ ‏ ‏أُهَرِيقَ ‏ ‏عَلَيْهِ ‏ ‏الْمَاءُ ‏","","",""],[11690,11690,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَنَفَّسُ فِي إِنَائِهِ ثَلَاثًا ‏ ‏وَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَتَنَفَّسُ ثَلَاثًا ‏","","",""],[11691,11691,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏الْأَخْضَرِ بْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَكَا إِلَيْهِ الْحَاجَةَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا عِنْدَكَ شَيْءٌ فَأَتَاهُ ‏ ‏بِحِلْسٍ ‏ ‏وَقَدَحٍ وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَشْتَرِي هَذَا فَقَالَ رَجُلٌ أَنَا آخُذُهُمَا بِدِرْهَمٍ قَالَ مَنْ يَزِيدُ عَلَى دِرْهَمٍ فَسَكَتَ الْقَوْمُ فَقَالَ مَنْ يَزِيدُ عَلَى دِرْهَمٍ فَقَالَ رَجُلٌ أَنَا آخُذُهُمَا بِدِرْهَمَيْنِ قَالَ هُمَا لَكَ ثُمَّ قَالَ ‏ ‏إِنَّ الْمَسْأَلَةَ لَا تَحِلُّ إِلَّا لِأَحَدِ ثَلَاثٍ ذِي دَمٍ مُوجِعٍ أَوْ غُرْمٍ مُفْظِعٍ أَوْ فَقْرٍ مُدْقِعٍ ‏","","",""],[11692,11692,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا يَفْتَتِحُونَ الْقِرَاءَةَ ‏ ‏بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏}","","",""],[11693,11693,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ ثُمَّ يَجِيءُ أَحَدُنَا إِلَى ‏ ‏بَنِي سَلِمَةَ ‏ ‏وَهُوَ يَرَى مَوَاقِعَ نَبْلِهِ ‏","","",""],[11694,11694,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏ابْنٌ يُقَالُ لَهُ ‏ ‏أَبُو عُمَيْرٍ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَاحِكُهُ قَالَ فَرَآهُ حَزِينًا فَقَالَ يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[11695,11695,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَنَسٌ ‏ ‏عَنْ بَيْعِ الثَّمَرِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ثَمَرَةِ النَّخْلِ حَتَّى ‏ ‏تَزْهُوَ ‏ ‏قِيلَ ‏ ‏لِأَنَسٍ ‏ ‏مَا ‏ ‏تَزْهُو ‏ ‏قَالَ تَحْمَرُّ ‏","","",""],[11696,11696,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَقَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَلَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْخَمْرِ بِالْجَرِيدِ وَالنِّعَالِ وَجَلَدَ ‏ ‏أَبُو بَكْرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فِي حَدِيثِهِ أَرْبَعِينَ ‏ ‏فَلَمَّا كَانَ ‏ ‏عُمَرُ ‏ ‏دَنَا النَّاسُ مِنْ الرِّيفِ وَالْقُرَى قَالَ لِأَصْحَابِهِ مَا تَرَوْنَ قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏اجْعَلْهَا كَأَخَفِّ الْحُدُودِ فَجَلَدَ ‏ ‏عُمَرُ ‏ ‏ثَمَانِينَ ‏","","",""],[11697,11697,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخَيْبَرَ ‏ ‏فَقَالَ أَكَلْتُ الْحُمُرَ مَرَّتَيْنِ قَالَ ثُمَّ جَاءَ فَقَالَ أَفْنَيْتُ الْحُمُرَ قَالَ فَنَادَى إِنَّ اللَّهَ وَرَسُولَهُ ‏ ‏يَنْهَيَانِكُمْ عَنْ لَحْمِ الْحُمُرِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏","","",""],[11698,11698,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يُسَلِّمُونَ عَلَيْنَا فَكَيْفَ نَرُدُّ عَلَيْهِمْ قَالَ ‏ ‏فَقُولُوا وَعَلَيْكُمْ ‏ ‏وَحَجَّاجٌ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏لَمْ أَسْأَلْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ هَذَا الْحَدِيثِ هَلْ سَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏","","",""],[11699,11699,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَتَبْقَى مِنْهُ اثْنَتَانِ الْحِرْصُ وَالْأَمَلُ ‏","","",""],[11700,11700,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏مَنْ يَنْظُرُ مَا فَعَلَ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَانْطَلَقَ ‏ ‏ابْنُ مَسْعُودٍ ‏ ‏فَوَجَدَ ابْنَيْ ‏ ‏عَفْرَاءَ ‏ ‏قَدْ ضَرَبَاهُ حَتَّى ‏ ‏بَرَدَ ‏ ‏فَأَخَذَ بِلِحْيَتِهِ فَقَالَ أَنْتَ ‏ ‏أَبُو جَهْلٍ ‏ ‏فَقَالَ وَهَلْ فَوْقَ رَجُلٍ قَتَلْتُمُوهُ ‏ ‏أَوْ قَتَلَهُ قَوْمُهُ ‏","","",""],[11701,11701,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏لَنْ تَنَالُوا ‏ ‏الْبِرَّ ‏ ‏حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ ‏} ‏وَ ‏ { ‏مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا ‏} ‏قَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَسُولَ اللَّهِ وَحَائِطِي الَّذِي كَانَ بِمَكَانِ كَذَا وَكَذَا وَاللَّهِ لَوْ اسْتَطَعْتُ أَنْ أُسِرَّهَا لَمْ أُعْلِنْهَا قَالَ ‏ ‏اجْعَلْهُ فِي ‏ ‏فُقَرَاءِ أَهْلِكَ ‏","","",""],[11702,11702,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏أَعْوَرُ الْعَيْنِ الشِّمَالِ عَلَيْهَا ‏ ‏ظَفَرَةٌ ‏ ‏غَلِيظَةٌ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ ‏ ‏قَالَ وَكُفْرٌ ‏","","",""],[11703,11703,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي صَلَاتِهِمْ فَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11704,11704,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَّى بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏لَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَاضِعًا عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَدَمَهُ وَيُسَمِّي وَيُكَبِّرُ ‏","","",""],[11705,11705,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِي ‏ ‏وَرُبَّمَا قَالَ مِنْ وَرَاءِ ظَهْرِي ‏ ‏إِذَا رَكَعْتُمْ وَإِذَا سَجَدْتُمْ ‏","","",""],[11706,11706,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ انْبِسَاطَ الْكَلْبِ ‏","","",""],[11707,11707,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ يَدْعُو عَلَى حَيٍّ مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏ثُمَّ تَرَكَهُ ‏","","",""],[11708,11708,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَإِذَا أَنَا بِنَهْرٍ حَافَتَاهُ خِيَامُ اللُّؤْلُؤِ فَضَرَبْتُ بِيَدِي فِي مَجْرَى الْمَاءِ فَإِذَا مِسْكٌ أَذْفَرُ قُلْتُ يَا ‏ ‏جِبْرِيلُ ‏ ‏مَا هَذَا قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ اللَّهُ ‏ ‏أَوْ أَعْطَاكَ رَبُّكَ عَزَّ وَجَلَّ ‏","","",""],[11709,11709,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ يَدْعُو عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَقَالَ ‏ ‏عُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ ‏","","",""],[11710,11710,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَجْتَمِعُ الْمُؤْمِنُونَ يَوْمَ الْقِيَامَةِ فَيُلْهَمُونَ ذَلِكَ فَيَقُولُونَ لَوْ اسْتَشْفَعْنَا عَلَى رَبِّنَا عَزَّ وَجَلَّ فَأَرَاحَنَا مِنْ مَكَانِنَا هَذَا فَيَأْتُونَ ‏ ‏آدَمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَيَقُولُونَ يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ أَبُو الْبَشَرِ خَلَقَكَ اللَّهُ عَزَّ وَجَلَّ بِيَدِهِ وَأَسْجَدَ لَكَ مَلَائِكَتَهُ وَعَلَّمَكَ أَسْمَاءَ كُلِّ شَيْءٍ فَاشْفَعْ لَنَا إِلَى رَبِّنَا عَزَّ وَجَلَّ يُرِيحُنَا مِنْ مَكَانِنَا هَذَا فَيَقُولُ لَهُمْ ‏ ‏آدَمُ ‏ ‏لَسْتُ هُنَاكُمْ وَيَذْكُرُ ذَنْبَهُ الَّذِي أَصَابَ ‏ ‏فَيَسْتَحْيِي رَبَّهُ عَزَّ وَجَلَّ وَيَقُولُ وَلَكِنْ ائْتُوا ‏ ‏نُوحًا ‏ ‏فَإِنَّهُ أَوَّلُ رَسُولٍ بَعَثَهُ اللَّهُ إِلَى الْأَرْضِ فَيَأْتُونَ ‏ ‏نُوحًا ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَيَذْكُرُ لَهُمْ خَطِيئَتَهُ وَسُؤَالَهُ رَبَّهُ عَزَّ وَجَلَّ مَا لَيْسَ لَهُ بِهِ عِلْمٌ ‏ ‏فَيَسْتَحْيِي رَبَّهُ بِذَلِكَ وَلَكِنْ ائْتُوا ‏ ‏إِبْرَاهِيمَ خَلِيلَ الرَّحْمَنِ ‏ ‏عَزَّ وَجَلَّ فَيَأْتُونَ فَيَقُولُ لَسْتُ هُنَاكُمْ وَلَكِنْ ائْتُوا ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَبْدًا كَلَّمَهُ اللَّهُ وَأَعْطَاهُ التَّوْرَاةَ فَيَأْتُونَ ‏ ‏مُوسَى ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَيَذْكُرُ لَهُمْ النَّفْسَ الَّتِي قَتَلَ بِغَيْرِ نَفْسٍ ‏ ‏فَيَسْتَحْيِي رَبَّهُ مِنْ ذَلِكَ وَلَكِنْ ائْتُوا ‏ ‏عِيسَى ‏ ‏عَبْدَ اللَّهِ وَرَسُولَهُ وَكَلِمَتَهُ وَرُوحَهُ فَيَأْتُونَ ‏ ‏عِيسَى ‏ ‏فَيَقُولُ لَسْتُ هُنَاكُمْ وَلَكِنْ ائْتُوا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدًا غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ فَيَأْتُونِي ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏هَذَا الْحَرْفَ ‏ ‏فَأَقُومُ ‏ ‏فَأَمْشِي بَيْنَ ‏ ‏سِمَاطَيْنِ ‏ ‏مِنْ الْمُؤْمِنِينَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏حَتَّى أَسْتَأْذِنَ عَلَى رَبِّي عَزَّ وَجَلَّ فَيُؤْذَنَ لِي فَإِذَا رَأَيْتُ رَبِّي وَقَعْتُ ‏ ‏أَوْ خَرَرْتُ ‏ ‏سَاجِدًا إِلَى رَبِّي عَزَّ وَجَلَّ فَيَدَعُنِي مَا شَاءَ اللَّهُ أَنْ يَدَعَنِي قَالَ ثُمَّ يُقَالُ ‏ ‏ارْفَعْ ‏ ‏مُحَمَّدُ ‏ ‏قُلْ تُسْمَعْ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُ بِتَحْمِيدٍ يُعَلِّمُنِيهِ ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُدْخِلُهُمْ الْجَنَّةَ ثُمَّ أَعُودُ إِلَيْهِ الثَّانِيَةَ فَإِذَا رَأَيْتُ رَبِّي عَزَّ وَجَلَّ وَقَعْتُ ‏ ‏أَوْ خَرَرْتُ ‏ ‏سَاجِدًا لِرَبِّي فَيَدَعُنِي مَا شَاءَ اللَّهُ أَنْ يَدَعَنِي ثُمَّ يُقَالُ ارْفَعْ ‏ ‏مُحَمَّدُ ‏ ‏قُلْ تُسْمَعْ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُهُ بِتَحْمِيدٍ يُعَلِّمُنِيهِ ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُدْخِلُهُمْ الْجَنَّةَ ثُمَّ أَعُودُ إِلَيْهِ الثَّالِثَةَ فَإِذَا رَأَيْتُ رَبِّي وَقَعْتُ ‏ ‏أَوْ خَرَرْتُ ‏ ‏سَاجِدًا لِرَبِّي عَزَّ وَجَلَّ فَيَدَعُنِي مَا شَاءَ اللَّهُ أَنْ يَدَعَنِي ثُمَّ يُقَالُ ارْفَعْ ‏ ‏مُحَمَّدُ ‏ ‏وَقُلْ تُسْمَعْ وَسَلْ ‏ ‏تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَحْمَدُهُ بِتَحْمِيدٍ يُعَلِّمُنِيهِ ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا فَأُدْخِلُهُمْ الْجَنَّةَ ثُمَّ أَعُودُ الرَّابِعَةَ فَأَقُولُ يَا رَبِّ مَا بَقِيَ إِلَّا مَنْ حَبَسَهُ الْقُرْآنُ فَحَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَيَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ شَعِيرَةً ثُمَّ يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ بُرَّةً ثُمَّ يَخْرُجُ مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ذَرَّةً ‏","","",""],[11711,11711,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ قَالَهُ مَرَّتَيْنِ ‏ ‏وَقَالَ مَرَّةً مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏","","",""],[11712,11712,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ ‏ ‏أَنَسًا ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ فِي صَلَاتِهِمْ قَالَ فَاشْتَدَّ فِي ذَلِكَ حَتَّى قَالَ لَيَنْتَهُنَّ عَنْ ذَلِكَ أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ ‏","","",""],[11713,11713,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمَرْأَةُ مِنْ نِسَائِهِ ‏ ‏يَغْتَسِلَانِ مِنْ إِنَاءٍ وَاحِدٍ وَكَانَ يَغْتَسِلُ بِخَمْسِ ‏ ‏مَكَاكِيَّ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏","","",""],[11714,11714,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏وَكَّلَ بِالرَّحِمِ مَلَكًا قَالَ أَيْ رَبِّ ‏ ‏نُطْفَةٌ ‏ ‏أَيْ رَبِّ ‏ ‏عَلَقَةٌ ‏ ‏أَيْ رَبِّ ‏ ‏مُضْغَةٌ ‏ ‏فَإِذَا قَضَى الرَّبُّ عَزَّ وَجَلَّ خَلْقَهَا قَالَ ‏ ‏أَيْ رَبِّ أَشَقِيٌّ أَوْ سَعِيدٌ ذَكَرًا أَوْ أُنْثَى فَمَا الرِّزْقُ وَمَا الْأَجَلُ قَالَ فَيَكْتُبُ كَذَلِكَ فِي بَطْنِ أُمِّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏بِمَكَّةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ أَنَسٍ أَبُو مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[11715,11715,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏تُصُدِّقَ ‏ ‏عَلَيْهَا ‏ ‏بِصَدَقَةٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ ‏","","",""],[11716,11716,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏عَجِبْتُ لِلْمُؤْمِنِ إِنَّ اللَّهَ لَمْ يَقْضِ قَضَاءً إِلَّا كَانَ خَيْرًا لَهُ ‏","","",""],[11717,11717,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُصْبَرَ ‏ ‏الْبَهَائِمُ ‏","","",""],[11718,11718,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنْ ‏ ‏الزُّبَيْرِ بْنِ عَدِيٍّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَا يَأْتِي عَلَيْكُمْ زَمَانٌ إِلَّا هُوَ شَرٌّ مِنْ الزَّمَانِ الَّذِي كَانَ قَبْلَهُ سَمِعْنَا ذَلِكَ مِنْ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتَيْنِ ‏","","",""],[11719,11719,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَيَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏نَفِيعٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أَحَدٍ يَوْمَ الْقِيَامَةِ غَنِيٍّ وَلَا فَقِيرٍ إِلَّا وَدَّ أَنَّمَا كَانَ أُوتِيَ مِنْ الدُّنْيَا قُوتًا ‏ ‏قَالَ ‏ ‏يَعْلَى ‏ ‏فِي الدُّنْيَا ‏","","",""],[11720,11720,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ذَا الْأُذُنَيْنِ ‏","","",""],[11721,11721,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏مَعَ نِسَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُنَّ يَسُوقُ بِهِنَّ سَوَّاقٌ فَأَتَى عَلَيْهِنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيْ ‏ ‏أَوْ يَا ‏ ‏أَنْجَشَةُ ‏ ‏سَوْقَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[11722,11722,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الْعَجْزِ وَالْكَسَلِ ‏ ‏وَالْهَرَمِ ‏ ‏وَالْبُخْلِ وَالْجُبْنِ وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَقَدْ ذَكَرَ فِيهِ الْمَحْيَا وَالْمَمَاتَ ‏","","",""],[11723,11723,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏عَطَسَ رَجُلَانِ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَمَّتَ ‏ ‏أَوْ ‏ ‏سَمَّتَ ‏ ‏أَحَدَهُمَا فَقَالَ ‏ ‏إِنَّ هَذَا حَمِدَ اللَّهَ عَزَّ وَجَلَّ وَإِنَّ ذَاكَ لَمْ يَحْمَدْ اللَّهَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَرُبَّمَا قَالَ هَذَا أَوْ نَحْوَهُ ‏","","",""],[11724,11724,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏لَيَرْضَى عَنْ الْعَبْدِ أَنْ يَأْكُلَ الْأُكْلَةَ أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَ اللَّهَ عَزَّ وَجَلَّ ‏ ‏عَلَيْهَا ‏","","",""],[11725,11725,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْبَاطُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَتْ عَامَّةُ وَصِيَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ حَضَرَهُ الْمَوْتُ ‏ ‏الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُمْ حَتَّى جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُغَرْغِرُ ‏ ‏بِهَا صَدْرُهُ وَمَا يَكَادُ ‏ ‏يُفِيضُ ‏ ‏بِهَا لِسَانُهُ ‏","","",""],[11726,11726,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏بُرَيْدِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا ‏ ‏اسْتَجَارَ ‏ ‏عَبْدٌ مِنْ النَّارِ ثَلَاثَ مِرَارٍ إِلَّا قَالَتْ النَّارُ اللَّهُمَّ ‏ ‏أَجِرْهُ ‏ ‏مِنِّي وَلَا يَسْأَلُ الْجَنَّةَ إِلَّا قَالَتْ الْجَنَّةُ اللَّهُمَّ أَدْخِلْهُ إِيَّايَ ‏","","",""],[11727,11727,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏مَنْ كَانَ ذَبَحَ قَبْلَ الصَّلَاةِ فَلْيُعِدْ فَقَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ هَذَا يَوْمٌ ‏ ‏يُشْتَهَى فِيهِ اللَّحْمُ وَذَكَرَ هَنَةً مِنْ جِيرَانِهِ كَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَّقَهُ قَالَ وَعِنْدِي جَذَعَةٌ هِيَ أَحَبُّ إِلَيَّ مِنْ شَاتَيْ لَحْمٍ قَالَ فَرَخَّصَ لَهُ قَالَ ‏ ‏فَلَا أَدْرِي أَبَلَغَتْ رُخْصَتُهُ مَنْ سِوَاهُ أَوْ لَا ‏ ‏قَالَ ثُمَّ انْكَفَأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى كَبْشَيْنِ فَذَبَحَهُمَا فَقَامَ النَّاسُ إِلَى غُنَيْمَةٍ فَتَوَزَّعُوهَا ‏ ‏أَوْ قَالَ فَتَجَزَّعُوهَا ‏","","",""],[11728,11728,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏أَخَذَ ‏ ‏الرَّايَةَ ‏ ‏زَيْدٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏جَعْفَرٌ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَأُصِيبَ ثُمَّ أَخَذَهَا ‏ ‏خَالِدٌ ‏ ‏عَنْ غَيْرِ ‏ ‏إِمْرَةٍ ‏ ‏فَفَتَحَ اللَّهُ عَلَيْهِ وَقَالَ مَا يَسُرُّهُمْ ‏ ‏أَوْ قَالَ مَا يَسُرُّنِي ‏ ‏أَنَّهُمْ عِنْدَنَا قَالَ وَإِنَّ عَيْنَيْهِ لَتَذْرِفَانِ ‏","","",""],[11729,11729,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعُ بْنُ الْجَرَّاحِ الرُّؤَاسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏يُوسُفَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الرُّقْيَةِ ‏ ‏مِنْ الْعَيْنِ ‏ ‏وَالْحُمَةِ ‏ ‏وَالنَّمْلَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[11730,11730,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَعْرٌ ‏ ‏يُصِيبُ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏يَضْرِبُ ‏ ‏مَنْكِبَيْهِ ‏","","",""],[11731,11731,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ بْنِ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أُتِيَ بِطِيبٍ لَمْ يَرُدَّهُ ‏","","",""],[11732,11732,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَإِسْحَاقُ الْأَزْرَقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ عِنْدَ أَهْلِ بَيْتٍ قَالَ ‏ ‏أَفْطَرَ عِنْدَكُمْ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمْ الْأَبْرَارُ وَتَنَزَّلَتْ عَلَيْكُمْ الْمَلَائِكَةُ ‏","","",""],[11733,11733,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ مَوْضِعُ ‏ ‏مَسْجِدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏وَكَانَ فِيهِ نَخْلُ وَقُبُورُ الْمُشْرِكِينَ فَقَالَ لَهُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَامِنُونِي ‏ ‏بِهِ فَقَالُوا لَا نَأْخُذُ لَهُ ثَمَنًا وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْنِيهِ وَهُمْ يُنَاوِلُونَهُ وَهُوَ يَقُولُ ‏ ‏أَلَا إِنَّ الْعَيْشَ عَيْشُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَبْلَ أَنْ ‏ ‏يُبْنَى الْمَسْجِدُ حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ ‏","","",""],[11734,11734,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَالدَّسْتُوَائِيِّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏طِيَرَةَ ‏ ‏وَيُعْجِبُنِي الْفَأْلُ قَالَ وَالْفَأْلُ الْكَلِمَةُ الْحَسَنَةُ الطَّيِّبَةُ ‏","","",""],[11735,11735,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏غَالِبٍ ‏ ‏هَكَذَا قَالَ ‏ ‏وَكِيعٌ ‏ ‏غَالِبٍ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏أَبُو غَالِبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ أُتِيَ بِجِنَازَةِ رَجُلٍ ‏ ‏فَقَامَ عِنْدَ رَأْسِ السَّرِيرِ ثُمَّ أُتِيَ بِجِنَازَةِ امْرَأَةٍ فَقَامَ أَسْفَلَ مِنْ ذَلِكَ حِذَاءَ السَّرِيرِ فَلَمَّا صَلَّى قَالَ لَهُ ‏ ‏الْعَلَاءُ بْنُ زِيَادٍ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏أَهَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ مِنْ الرَّجُلِ وَالْمَرْأَةِ نَحْوًا مِمَّا رَأَيْتُكَ فَعَلْتَ قَالَ نَعَمْ قَالَ فَأَقْبَلَ عَلَيْنَا ‏ ‏الْعَلَاءُ بْنُ زِيَادٍ ‏ ‏فَقَالَ احْفَظُوا ‏","","",""],[11736,11736,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ وَرْدَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَصْحَابِهِ ذَاتَ يَوْمٍ مَنْ شَهِدَ مِنْكُمْ الْيَوْمَ جَنَازَةً قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ مَنْ ‏ ‏عَادَ ‏ ‏مِنْكُمْ مَرِيضًا قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ مَنْ تَصَدَّقَ قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ مَنْ أَصْبَحَ صَائِمًا قَالَ ‏ ‏عُمَرُ ‏ ‏أَنَا قَالَ ‏ ‏وَجَبَتْ وَجَبَتْ ‏","","",""],[11737,11737,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏أَنْفَجْنَا أَرْنَبًا ‏ ‏بِمَرِّ الظَّهْرَانِ ‏ ‏قَالَ فَسَعَى عَلَيْهَا الْغِلْمَانُ حَتَّى لَغِبُوا قَالَ فَأَدْرَكْتُهَا فَأَتَيْتُ بِهَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏فَذَبَحَهَا ثُمَّ بَعَثَ مَعِي بِوَرِكِهَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَبِلَ ‏","","",""],[11738,11738,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْبَحُ أُضْحِيَّتَهُ بِيَدِهِ ‏","","",""],[11739,11739,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى الثَّعْلَبِيِّ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ ‏ ‏الْقَضَاءَ ‏ ‏وُكِلَ إِلَيْهِ وَمَنْ أُجْبِرَ عَلَيْهِ نَزَلَ عَلَيْهِ مَلَكٌ ‏ ‏فَيُسَدِّدُهُ ‏","","",""],[11740,11740,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَشْرَبَ الرَّجُلُ قَائِمًا ‏","","",""],[11741,11741,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عِصَامٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَنَفَّسُ فِي الْإِنَاءِ ثَلَاثًا وَيَقُولُ هَذَا أَهْنَأُ ‏ ‏وَأَمْرَأُ ‏ ‏وَأَبْرَأُ ‏","","",""],[11742,11742,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِمُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏أَسَمِعْتَ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلنُّعْمَانِ بْنِ مُقَرِّنٍ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ قَالَ نَعَمْ ‏","","",""],[11743,11743,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ الْجَزَرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ ابْنَةِ أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏وَفِي الْبَيْتِ ‏ ‏قِرْبَةٌ ‏ ‏مُعَلَّقَةٌ ‏ ‏فَشَرِبَ مِنْ فِيهَا وَهُوَ قَائِمٌ قَالَ فَقَطَعَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏فَمَ ‏ ‏الْقِرْبَةِ ‏ ‏فَهُوَ عِنْدَنَا ‏","","",""],[11744,11744,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَيْتَامٍ وَرِثُوا خَمْرًا فَقَالَ ‏ ‏أَهْرِقْهَا ‏ ‏قَالَ أَفَلَا نَجْعَلُهَا خَلًّا قَالَ لَا ‏","","",""],[11745,11745,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ تَمْرَةً فَقَالَ ‏ ‏لَوْلَا أَنْ تَكُونِي مِنْ ‏ ‏الصَّدَقَةِ ‏ ‏لَأَكَلْتُكِ ‏","","",""],[11746,11746,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏جَرِيرِ بْنِ حَازِمٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏عَلَى ‏ ‏الْأَخْدَعَيْنِ ‏ ‏وَعَلَى الْكَاهِلِ ‏","","",""],[11747,11747,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ أَبِي قَالَ ‏ ‏فِي النَّارِ قَالَ فَلَمَّا رَأَى مَا فِي وَجْهِهِ قَالَ إِنَّ أَبِي وَأَبَاكَ فِي النَّارِ ‏","","",""],[11748,11748,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَزْرَةُ بْنُ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَنَفَّسُ فِي الْإِنَاءِ ثَلَاثًا ‏","","",""],[11749,11749,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏يُوسُفَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الرُّقْيَةِ ‏ ‏مِنْ الْعَيْنِ وَالنَّمْلَةِ ‏ ‏وَالْحُمَةِ ‏","","",""],[11750,11750,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَصَمِّ ‏ ‏سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يُتِمُّونَ التَّكْبِيرَ فَيُكَبِّرُونَ إِذَا سَجَدُوا وَإِذَا رَفَعُوا ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَوْ خَفَضُوا ‏ ‏قَالَ كَبَّرُوا ‏","","",""],[11751,11751,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُخْتَارَ بْنَ فُلْفُلٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ الشُّرْبِ فِي الْأَوْعِيَةِ فَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُزَفَّتَةِ ‏ ‏وَقَالَ كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[11752,11752,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ امْرَأَةً لَقِيَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي طَرِيقٍ مِنْ طُرُقِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي إِلَيْكَ حَاجَةً قَالَ يَا أُمَّ فُلَانٍ اجْلِسِي فِي أَيِّ نَوَاحِي السِّكَكِ شِئْتِ أَجْلِسْ إِلَيْكِ قَالَ فَقَعَدَتْ ‏ ‏فَقَعَدَ إِلَيْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى قَضَتْ حَاجَتَهَا ‏","","",""],[11753,11753,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ قِرَاءَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏يَمُدُّ بِهَا صَوْتَهُ مَدًّا ‏","","",""],[11754,11754,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَالِطُنَا ‏ ‏حَتَّى يَقُولَ لِأَخٍ لِي صَغِيرٍ يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏ ‏طَائِرٌ كَانَ يَلْعَبُ بِهِ قَالَ ‏ ‏وَنُضِحَ ‏ ‏بِسَاطٌ لَنَا قَالَ فَصَلَّى عَلَيْهِ وَصَفَّنَا خَلْفَهُ ‏","","",""],[11755,11755,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدٍ الْعَمِّيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِيَاسٍ يَعْنِي مُعَاوِيَةَ بْنَ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدُّعَاءُ لَا يُرَدُّ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ ‏","","",""],[11756,11756,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْزِلُ مِنْ الْمِنْبَرِ يَوْمَ الْجُمُعَةِ فَيُكَلِّمُهُ الرَّجُلُ فِي الْحَاجَةِ فَيُكَلِّمُهُ ثُمَّ يَتَقَدَّمُ إِلَى مُصَلَّاهُ فَيُصَلِّي ‏","","",""],[11757,11757,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَيَبْقَى مِنْهُ اثْنَتَانِ الْحِرْصُ وَالْأَمَلُ ‏","","",""],[11758,11758,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَتَّابٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ هُرْمُزَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَايَعْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ فَقَالَ فِيمَا اسْتَطَعْتُمْ ‏","","",""],[11759,11759,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَمْزَةَ الضَّبِّيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا نَزَلَ مَنْزِلًا لَمْ يَرْتَحِلْ حَتَّى يُصَلِّيَ الظُّهْرَ قَالَ فَقَالَ ‏ ‏مُحَمَّدُ بْنُ عُمَرَ ‏ ‏لِأَنَسٍ ‏ ‏يَا ‏ ‏أَبَا حَمْزَةَ ‏ ‏وَإِنْ كَانَ بِنِصْفِ النَّهَارِ قَالَ وَإِنْ كَانَ بِنِصْفِ النَّهَارِ ‏","","",""],[11760,11760,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو خُزَيْمَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ رَجُلًا يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَسْأَلُكَ ‏ ‏بِأَنَّ ‏ ‏لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ ‏ ‏الْمَنَّانَ ‏ ‏بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ ذَا الْجَلَالِ وَالْإِكْرَامِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ سَأَلْتَ اللَّهَ بِاسْمِ اللَّهِ الْأَعْظَمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ وَإِذَا سُئِلَ بِهِ أَعْطَى ‏","","",""],[11761,11761,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏مِسْعَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏احْتَجَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ لَا يَظْلِمُ أَحَدًا أَجْرًا ‏","","",""],[11762,11762,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ عَلِّمْنِي كَلِمَاتٍ أَدْعُو بِهِنَّ قَالَ ‏ ‏تُسَبِّحِينَ اللَّهَ عَزَّ وَجَلَّ عَشْرًا وَتَحْمَدِينَهُ عَشْرًا وَتُكَبِّرِينَهُ عَشْرًا ثُمَّ سَلِي حَاجَتَكِ فَإِنَّهُ يَقُولُ قَدْ فَعَلْتُ قَدْ فَعَلْتُ ‏","","",""],[11763,11763,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الْمَاجِشُونَ ‏ ‏عَنْ ‏ ‏صَدَقَةَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏الْنُمَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏قَدْ افْتَرَقَتْ عَلَى اثْنَتَيْنِ وَسَبْعِينَ فِرْقَةً وَأَنْتُمْ تَفْتَرِقُونَ عَلَى مِثْلِهَا كُلُّهَا فِي النَّارِ إِلَّا فِرْقَةً ‏","","",""],[11764,11764,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَأُحَدِّثَنَّكُمْ بِحَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُحَدِّثُكُمْ أَحَدٌ بَعْدِي سَمِعْتُهُ يَقُولُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَكُونَ فِي الْخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ وَيَكْثُرَ النِّسَاءُ وَيَقِلَّ الرِّجَالُ ‏","","",""],[11765,11765,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَرْتُ لَيْلَةَ أُسْرِيَ بِي عَلَى ‏ ‏مُوسَى ‏ ‏فَرَأَيْتُهُ قَائِمًا ‏ ‏يُصَلِّي فِي قَبْرِهِ ‏","","",""],[11766,11766,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَرْتُ لَيْلَةَ ‏ ‏أُسْرِيَ ‏ ‏بِي عَلَى قَوْمٍ تُقْرَضُ شِفَاهُهُمْ بِمَقَارِيضَ مِنْ نَارٍ قَالَ قُلْتُ مَنْ هَؤُلَاءِ قَالُوا خُطَبَاءُ مِنْ أَهْلِ الدُّنْيَا كَانُوا يَأْمُرُونَ النَّاسَ بِالْبِرِّ وَيَنْسَوْنَ أَنْفُسَهُمْ وَهُمْ يَتْلُونَ ‏ ‏الْكِتَابَ ‏ ‏أَفَلَا يَعْقِلُونَ ‏","","",""],[11767,11767,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ ‏ ‏أُوذِيتُ فِي اللَّهِ عَزَّ وَجَلَّ وَمَا ‏ ‏يُؤْذَى أَحَدٌ وَأُخِفْتُ مِنْ اللَّهِ وَمَا يُخَافُ أَحَدٌ وَلَقَدْ أَتَتْ عَلَيَّ ثَلَاثَةٌ مِنْ بَيْنِ يَوْمٍ وَلَيْلَةٍ وَمَا لِي وَلِعِيَالِي طَعَامٌ يَأْكُلُهُ ذُو كَبِدٍ إِلَّا مَا يُوَارِي إِبِطَ ‏ ‏بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ فِي هَذَا الْحَدِيثِ أَتَتْ عَلَيَّ ثَلَاثُونَ مِنْ بَيْنِ يَوْمٍ وَلَيْلَةٍ ‏","","",""],[11768,11768,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا عَلَيْكُمْ أَنْ لَا تَعْجَبُوا بِأَحَدٍ حَتَّى تَنْظُرُوا بِمَ يُخْتَمُ لَهُ ‏ ‏فَإِنَّ الْعَامِلَ يَعْمَلُ زَمَانًا مِنْ عُمْرِهِ أَوْ بُرْهَةً مِنْ دَهْرِهِ بِعَمَلٍ صَالِحٍ لَوْ مَاتَ عَلَيْهِ دَخَلَ الْجَنَّةَ ثُمَّ يَتَحَوَّلُ فَيَعْمَلُ عَمَلًا سَيِّئًا وَإِنَّ الْعَبْدَ لَيَعْمَلُ الْبُرْهَةَ مِنْ دَهْرِهِ بِعَمَلٍ سَيِّئٍ لَوْ مَاتَ عَلَيْهِ دَخَلَ النَّارَ ثُمَّ يَتَحَوَّلُ فَيَعْمَلُ عَمَلًا صَالِحًا وَإِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا اسْتَعْمَلَهُ قَبْلَ مَوْتِهِ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ يَسْتَعْمِلُهُ قَالَ يُوَفِّقُهُ لِعَمَلٍ صَالِحٍ ثُمَّ يَقْبِضُهُ عَلَيْهِ ‏","","",""],[11769,11769,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا كَانَ يَكْتُبُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ كَانَ قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏وَكَانَ الرَّجُلُ إِذَا قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏جَدَّ فِينَا ‏ ‏يَعْنِي عَظُمَ ‏ ‏فَكَانَ النَّبِيُّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏يُمْلِي عَلَيْهِ غَفُورًا رَحِيمًا فَيَكْتُبُ عَلِيمًا حَكِيمًا فَيَقُولُ لَهُ النَّبِيُّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏اكْتُبْ كَذَا وَكَذَا اكْتُبْ كَيْفَ شِئْتَ ‏ ‏وَيُمْلِي عَلَيْهِ عَلِيمًا حَكِيمًا فَيَقُولُ أَكْتُبُ سَمِيعًا بَصِيرًا فَيَقُولُ اكْتُبْ اكْتُبْ كَيْفَ شِئْتَ فَارْتَدَّ ذَلِكَ الرَّجُلُ عَنْ الْإِسْلَامِ فَلَحِقَ بِالْمُشْرِكِينَ وَقَالَ أَنَا أَعْلَمُكُمْ ‏ ‏بِمُحَمَّدٍ ‏ ‏إِنْ كُنْتُ لَأَكْتُبُ مَا شِئْتُ فَمَاتَ ذَلِكَ الرَّجُلُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْأَرْضَ لَمْ تَقْبَلْهُ ‏ ‏و قَالَ ‏ ‏أَنَسٌ ‏ ‏فَحَدَّثَنِي ‏ ‏أَبُو طَلْحَةَ ‏ ‏أَنَّهُ أَتَى الْأَرْضَ الَّتِي مَاتَ فِيهَا ذَلِكَ الرَّجُلُ فَوَجَدَهُ ‏ ‏مَنْبُوذًا ‏ ‏فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏مَا شَأْنُ هَذَا الرَّجُلِ قَالُوا قَدْ دَفَنَّاهُ مِرَارًا فَلَمْ تَقْبَلْهُ الْأَرْضُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السَّهْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يَكْتُبُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏وَكَانَ الرَّجُلُ إِذَا قَرَأَ ‏ ‏الْبَقَرَةَ ‏ ‏وَآلَ ‏ ‏عِمْرَانَ ‏ ‏يُعَدُّ فِينَا عَظِيمًا فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏يَزِيدَ ‏","","",""],[11770,11770,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا طَلْحَةَ ‏ ‏فِي غَزْوَةِ ‏ ‏خَيْبَرَ ‏ ‏يُنَادِي ‏ ‏إِنَّ اللَّهَ وَرَسُولَهُ يَنْهَيَانِكُمْ عَنْ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ فَإِنَّهَا ‏ ‏رِجْسٌ ‏ ‏قَالَ ‏ ‏فَأُكْفِئَتْ ‏ ‏الْقُدُورُ ‏","","",""],[11771,11771,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏وَعَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏بِالْبَقِيعِ ‏ ‏فَنَادَى رَجُلٌ رَجُلًا يَا ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَالْتَفَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ الرَّجُلُ لَمْ أَعْنِكَ يَا رَسُولَ اللَّهِ إِنَّمَا عَنَيْتُ فُلَانًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِاسْمِي وَلَا تَكَنَّوْا بِكُنْيَتِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏فِي حَدِيثِهِ تَسَمَّوْا بِاسْمِي ‏","","",""],[11772,11772,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلَهُ رَجُلٌ عَنْ وَقْتِ صَلَاةِ الصُّبْحِ ‏ ‏فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ حِينَ طَلَعَ الْفَجْرُ ثُمَّ أَقَامَ فَصَلَّى فَلَمَّا كَانَ مِنْ الْغَدِ أَخَّرَ حَتَّى ‏ ‏أَسْفَرَ ‏ ‏ثُمَّ أَمَرَهُ أَنْ يُقِيمَ فَصَلَّى ثُمَّ دَعَا الرَّجُلَ فَقَالَ مَا بَيْنَ هَذَا وَهَذَا وَقْتٌ ‏","","",""],[11773,11773,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ مِنْ دُعَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏اللَّهُمَّ إِنْ شِئْتَ أَنْ لَا تُعْبَدَ بَعْدَ الْيَوْمِ ‏","","",""],[11774,11774,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَلْعَبُ مَعَ الصِّبْيَانِ فَأَتَاهُ آتٍ فَأَخَذَهُ فَشَقَّ ‏ ‏صَدْرَهُ ‏ ‏فَاسْتَخْرَجَ مِنْهُ ‏ ‏عَلَقَةً ‏ ‏فَرَمَى بِهَا وَقَالَ هَذِهِ نَصِيبُ الشَّيْطَانِ مِنْكَ ثُمَّ غَسَلَهُ فِي طَشْتٍ مِنْ ذَهَبٍ مِنْ مَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ لَأَمَهُ فَأَقْبَلَ الصِّبْيَانُ إِلَى ‏ ‏ظِئْرِهِ ‏ ‏قُتِلَ ‏ ‏مُحَمَّدٌ ‏ ‏قُتِلَ ‏ ‏مُحَمَّدٌ ‏ ‏فَاسْتَقْبَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ انْتَقَعَ لَوْنُهُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَلَقَدْ كُنَّا نَرَى أَثَرَ الْمَخِيطِ فِي صَدْرِهِ ‏","","",""],[11775,11775,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ امْرَأَةٍ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَأَتْ ذَلِكَ مِنْكُنَّ فَأَنْزَلَتْ فَلْتَغْتَسِلْ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏أَوَ يَكُونُ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ نَعَمْ مَاءُ الرَّجُلِ غَلِيظٌ أَبْيَضُ وَمَاءُ الْمَرْأَةِ أَصْفَرُ رَقِيقٌ فَأَيُّهُمَا سَبَقَ أَوْ عَلَا أَشْبَهَهُ الْوَلَدُ ‏","","",""],[11776,11776,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏وَكَانَ ‏ ‏وَاقِدٌ ‏ ‏مِنْ أَحْسَنِ النَّاسِ وَأَعْظَمِهِمْ وَأَطْوَلِهِمْ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏فَقَالَ لِي مَنْ أَنْتَ قُلْتُ أَنَا ‏ ‏وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ ‏ ‏قَالَ إِنَّكَ ‏ ‏بِسَعْدٍ ‏ ‏أَشْبَهُ ثُمَّ بَكَى وَأَكْثَرَ الْبُكَاءَ فَقَالَ رَحْمَةُ اللَّهِ عَلَى ‏ ‏سَعْدٍ ‏ ‏كَانَ مِنْ أَعْظَمِ النَّاسِ وَأَطْوَلِهِمْ ثُمَّ قَالَ بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشًا إِلَى ‏ ‏أُكَيْدِرَ ‏ ‏دُومَةَ ‏ ‏فَأَرْسَلَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجُبَّةٍ ‏ ‏مِنْ ‏ ‏دِيبَاجٍ ‏ ‏مَنْسُوجٍ فِيهِ الذَّهَبُ فَلَبِسَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ عَلَى الْمِنْبَرِ ‏ ‏أَوْ جَلَسَ ‏ ‏فَلَمْ يَتَكَلَّمْ ثُمَّ نَزَلَ فَجَعَلَ النَّاسُ يَلْمِسُونَ ‏ ‏الْجُبَّةَ ‏ ‏وَيَنْظُرُونَ إِلَيْهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَعْجَبُونَ مِنْهَا قَالُوا مَا رَأَيْنَا ثَوْبًا قَطُّ أَحْسَنَ ‏ ‏مِنْهُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَنَادِيلُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فِي الْجَنَّةِ أَحْسَنُ مِمَّا تَرَوْنَ ‏","","",""],[11777,11777,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَهْدَى ‏ ‏الْأُكَيْدِرُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَرَّةً مِنْ ‏ ‏مَنٍّ ‏ ‏فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الصَّلَاةِ ‏ ‏مَرَّ عَلَى الْقَوْمِ فَجَعَلَ يُعْطِي كُلَّ رَجُلٍ مِنْهُمْ قِطْعَةً فَأَعْطَى ‏ ‏جَابِرًا ‏ ‏قِطْعَةً ثُمَّ إِنَّهُ رَجَعَ إِلَيْهِ فَأَعْطَاهُ قِطْعَةً أُخْرَى فَقَالَ إِنَّكَ قَدْ أَعْطَيْتَنِي مَرَّةً قَالَ هَذَا لِبَنَاتِ ‏ ‏عَبْدِ اللَّهِ ‏","","",""],[11778,11778,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَعَوَّذُ مِنْ ثَمَانٍ الْهَمِّ ‏ ‏وَالْحَزَنِ ‏ ‏وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَغَلَبَةِ الدَّيْنِ وَغَلَبَةِ الْعَدُوِّ ‏","","",""],[11779,11779,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعْمَتَهُ عَلَيْكَ وَيَهْدِيَكَ صِرَاطًا مُسْتَقِيمًا ‏} ‏قَالَ الْمُسْلِمُونَ يَا رَسُولَ اللَّهِ هَنِيئًا لَكَ مَا أَعْطَاكَ اللَّهُ فَمَا لَنَا فَنَزَلَتْ ‏ { ‏لِيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ ‏ ‏تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَيُكَفِّرَ عَنْهُمْ سَيِّئَاتِهِمْ وَكَانَ ذَلِكَ عِنْدَ اللَّهِ فَوْزًا عَظِيمًا ‏}","","",""],[11780,11780,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏هَبَطَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ ثَمَانُونَ رَجُلًا مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فِي السِّلَاحِ مِنْ قِبَلِ ‏ ‏جَبَلِ التَّنْعِيمِ ‏ ‏فَدَعَا عَلَيْهِمْ فَأُخِذُوا وَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَهُوَ الَّذِي كَفَّ أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ ‏ ‏مَكَّةَ ‏ ‏مِنْ بَعْدِ أَنْ ‏ ‏أَظْفَرَكُمْ ‏ ‏عَلَيْهِمْ ‏} ‏قَالَ ‏ ‏يَعْنِي ‏ ‏جَبَلَ التَّنْعِيمِ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏","","",""],[11781,11781,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَلَا أَدْرِي أَشَيْءٌ نَزَلَ عَلَيْهِ أَمْ شَيْءٌ يَقُولُهُ وَهُوَ يَقُولُ ‏ ‏لَوْ كَانَ لِابْنِ ‏ ‏آدَمَ ‏ ‏وَادِيَانِ مِنْ مَالٍ لَابْتَغَى لَهُمَا ثَالِثًا وَلَا يَمْلَأُ جَوْفَ ابْنِ ‏ ‏آدَمَ ‏ ‏إِلَّا التُّرَابُ وَيَتُوبُ اللَّهُ عَلَى مَنْ تَابَ ‏","","",""],[11782,11782,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَتْ نِعَالُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُمَا قِبَالَانِ ‏","","",""],[11783,11783,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ يَعْنِي ابْنَ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏الزُّبَيْرَ بْنَ الْعَوَّامِ ‏ ‏وَعَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏شَكَوَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقَمْلَ فَرَخَّصَ لَهُمَا فِي لُبْسِ الْحَرِيرِ فَرَأَيْتُ عَلَى كُلِّ وَاحِدٍ مِنْهُمَا قَمِيصًا مِنْ حَرِيرٍ ‏","","",""],[11784,11784,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ حُسْنِ الصَّلَاةِ إِقَامَةَ الصَّفِّ ‏","","",""],[11785,11785,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏صَدَقَةُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏وَقَّتَ ‏ ‏لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَصِّ الشَّارِبِ وَتَقْلِيمِ الْأَظْفَارِ وَحَلْقِ الْعَانَةِ فِي كُلِّ أَرْبَعِينَ يَوْمًا مَرَّةً ‏","","",""],[11786,11786,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏إِنْ تَقَرَّبَ عَبْدِي مِنِّي شِبْرًا تَقَرَّبْتُ مِنْهُ ذِرَاعًا وَإِنْ تَقَرَّبَ مِنِّي ذِرَاعًا تَقَرَّبْتُ مِنْهُ بَاعًا وَإِنْ أَتَانِي مَاشِيًا أَتَيْتُهُ هَرْوَلَةً ‏","","",""],[11787,11787,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا هَاجَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْكَبُ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏رَدِيفُهُ ‏ ‏وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُعْرَفُ فِي الطَّرِيقِ لِاخْتِلَافِهِ إِلَى ‏ ‏الشَّامِ ‏ ‏وَكَانَ يَمُرُّ بِالْقَوْمِ فَيَقُولُونَ مَنْ هَذَا بَيْنَ يَدَيْكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَيَقُولُ هَادٍ يَهْدِينِي فَلَمَّا دَنَوْا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏بَعَثَ إِلَى الْقَوْمِ الَّذِينَ أَسْلَمُوا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏إِلَى ‏ ‏أَبِي أُمَامَةَ ‏ ‏وَأَصْحَابِهِ فَخَرَجُوا إِلَيْهِمَا فَقَالُوا ادْخُلَا آمِنَيْنِ مُطَاعَيْنِ فَدَخَلَا ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَمَا رَأَيْتُ يَوْمًا قَطُّ أَنْوَرَ وَلَا أَحْسَنَ مِنْ يَوْمِ دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏الْمَدِينَةَ ‏ ‏وَشَهِدْتُ وَفَاتَهُ فَمَا رَأَيْتُ يَوْمًا قَطُّ أَظْلَمَ وَلَا أَقْبَحَ مِنْ الْيَوْمِ الَّذِي تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ ‏","","",""],[11788,11788,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَذَ سَيْفًا يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ مَنْ يَأْخُذُ هَذَا السَّيْفَ فَأَخَذَهُ قَوْمٌ فَجَعَلُوا يَنْظُرُونَ إِلَيْهِ فَقَالَ مَنْ يَأْخُذُهُ بِحَقِّهِ ‏ ‏فَأَحْجَمَ ‏ ‏الْقَوْمُ فَقَالَ ‏ ‏أَبُو دُجَانَةَ سِمَاكٌ ‏ ‏أَنَا آخُذُ بِحَقِّهِ فَأَخَذَهُ فَفَلَقَ ‏ ‏هَامَ ‏ ‏الْمُشْرِكِينَ ‏","","",""],[11789,11789,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏مَنْ قَتَلَ رَجُلًا فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏فَقَتَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏عِشْرِينَ رَجُلًا فَأَخَذَ ‏ ‏أَسْلَابَهُمْ ‏","","",""],[11790,11790,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَبَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ لَا يَظْلِمُ الْمُؤْمِنَ حَسَنَةً يُعْطَى عَلَيْهَا فِي الدُّنْيَا وَيُثَابُ عَلَيْهَا فِي الْآخِرَةِ وَأَمَّا الْكَافِرُ ‏ ‏فَيُعْطِيهِ حَسَنَاتِهِ فِي الدُّنْيَا حَتَّى إِذَا ‏ ‏أَفْضَى ‏ ‏إِلَى الْآخِرَةِ لَمْ يَكُنْ لَهُ بِهَا حَسَنَةٌ يُعْطَى بِهَا خَيْرًا ‏","","",""],[11791,11791,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ أَصَابِعَهُ فَوَضَعَهَا عَلَى الْأَرْضِ فَقَالَ هَذَا ابْنُ ‏ ‏آدَمَ ‏ ‏ثُمَّ رَفَعَهَا خَلْفَ ذَلِكَ قَلِيلًا وَقَالَ هَذَا أَجَلُهُ ثُمَّ رَمَى بِيَدِهِ أَمَامَهُ قَالَ وَثَمَّ أَمَلُهُ ‏","","",""],[11792,11792,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا دَعَا جَعَلَ ظَاهِرَ كَفَّيْهِ مِمَّا يَلِي وَجْهَهُ وَبَاطِنَهُمَا مِمَّا ‏ ‏يَلِي ‏ ‏الْأَرْضَ ‏","","",""],[11793,11793,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏صَفِيَّةَ ‏ ‏وَقَعَتْ فِي سَهْمِ ‏ ‏دِحْيَةَ الْكَلْبِيِّ ‏ ‏فَقِيلَ يَا رَسُولَ اللَّهِ قَدْ وَقَعَتْ فِي سَهْمِ ‏ ‏دِحْيَةَ ‏ ‏جَارِيَةٌ جَمِيلَةٌ ‏ ‏فَاشْتَرَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِسَبْعَةِ أَرْؤُسٍ فَجَعَلَهَا عِنْدَ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏حَتَّى تَهَيَّأَ ‏ ‏وَتَعْتَدَّ ‏ ‏فِيمَا يَعْلَمُ ‏ ‏حَمَّادٌ ‏ ‏فَقَالَ النَّاسُ وَاللَّهِ مَا نَدْرِي أَتَزَوَّجَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ تَسَرَّاهَا فَلَمَّا حَمَلَهَا سَتَرَهَا وَأَرْدَفَهَا خَلْفَهُ فَعَرَفَ النَّاسُ أَنَّهُ قَدْ تَزَوَّجَهَا فَلَمَّا دَنَا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏أَوْضَعَ ‏ ‏النَّاسُ ‏ ‏وَأَوْضَعَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَذَلِكَ كَانُوا يَصْنَعُونَ فَعَثَرَتْ النَّاقَةُ ‏ ‏فَخَرَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَّتْ مَعَهُ وَأَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرْنَ فَقُلْنَ أَبْعَدَ اللَّهُ الْيَهُودِيَّةَ وَفَعَلَ بِهَا وَفَعَلَ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَتَرَهَا وَأَرْدَفَهَا خَلْفَهُ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَارَتْ ‏ ‏صَفِيَّةُ ‏ ‏لِدِحْيَةَ ‏ ‏فِي قَسْمِهِ فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ حَتَّى إِذَا جَعَلَهَا فِي ظَهْرِهِ نَزَلَ ثُمَّ ضَرَبَ عَلَيْهَا ‏ ‏الْقُبَّةَ ‏","","",""],[11794,11794,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ مَوْضِعُ ‏ ‏مَسْجِدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏وَكَانَ فِيهِ نَخْلٌ وَخِرَبٌ وَقُبُورٌ مِنْ قُبُورِ الْجَاهِلِيَّةِ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَامِنُونِي ‏ ‏فَقَالُوا لَا نَبْغِي بِهِ ثَمَنًا إِلَّا عِنْدَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّخْلِ فَقُطِعَ وَبِالْحَرْثِ فَأُفْسِدَ وَبِالْقُبُورِ ‏ ‏فَنُبِشَتْ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ ذَلِكَ ‏ ‏يُصَلِّي فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ حَيْثُ أَدْرَكَتْهُ الصَّلَاةُ ‏","","",""],[11795,11795,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ جَارًا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَارِسِيًّا كَانَ طَيِّبَ الْمَرَقِ فَصَنَعَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ جَاءَهُ يَدْعُوهُ فَقَالَ وَهَذِهِ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَ لَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ثُمَّ عَادَ يَدْعُوهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذِهِ قَالَ لَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَذِهِ قَالَ نَعَمْ فِي الثَّالِثَةِ ‏ ‏فَقَامَا ‏ ‏يَتَدَافَعَانِ ‏ ‏حَتَّى أَتَيَا مَنْزِلَهُ ‏","","",""],[11796,11796,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَدِينَةُ ‏ ‏يَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ الْمَلَائِكَةَ يَحْرُسُونَهَا فَلَا يَدْخُلُهَا ‏ ‏الدَّجَّالُ ‏ ‏وَلَا الطَّاعُونُ إِنْ شَاءَ اللَّهُ تَعَالَى ‏","","",""],[11797,11797,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى ‏","","",""],[11798,11798,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاهِدُوا الْمُشْرِكِينَ بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ وَأَلْسِنَتِكُمْ ‏","","",""],[11799,11799,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏يَؤُمُّ قَوْمَهُ فَدَخَلَ ‏ ‏حَرَامٌ ‏ ‏وَهُوَ يُرِيدُ أَنْ يَسْقِيَ نَخْلَهُ فَدَخَلَ الْمَسْجِدَ لِيُصَلِّيَ مَعَ الْقَوْمِ فَلَمَّا رَأَى ‏ ‏مُعَاذًا ‏ ‏طَوَّلَ ‏ ‏تَجَوَّزَ ‏ ‏فِي صَلَاتِهِ وَلَحِقَ بِنَخْلِهِ ‏ ‏يَسْقِيهِ فَلَمَّا قَضَى ‏ ‏مُعَاذٌ ‏ ‏الصَّلَاةَ قِيلَ لَهُ إِنَّ ‏ ‏حَرَامًا ‏ ‏دَخَلَ الْمَسْجِدَ فَلَمَّا رَآكَ طَوَّلْتَ ‏ ‏تَجَوَّزَ ‏ ‏فِي صَلَاتِهِ وَلَحِقَ بِنَخْلِهِ ‏ ‏يَسْقِيهِ قَالَ إِنَّهُ لَمُنَافِقٌ أَيَعْجَلُ عَنْ الصَّلَاةِ مِنْ أَجْلِ سَقْيِ نَخْلِهِ قَالَ فَجَاءَ ‏ ‏حَرَامٌ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمُعَاذٌ ‏ ‏عِنْدَهُ فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي أَرَدْتُ أَنْ أَسْقِيَ نَخْلًا لِي فَدَخَلْتُ الْمَسْجِدَ لِأُصَلِّيَ مَعَ الْقَوْمِ فَلَمَّا طَوَّلَ تَجَوَّزْتُ فِي صَلَاتِي وَلَحِقْتُ بِنَخْلِي ‏ ‏أَسْقِيهِ فَزَعَمَ أَنِّي مُنَافِقٌ فَأَقْبَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مُعَاذٍ ‏ ‏فَقَالَ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ ‏ ‏أَفَتَّانٌ ‏ ‏أَنْتَ ‏ ‏لَا تُطَوِّلْ بِهِمْ اقْرَأْ ‏ ‏بِسَبِّحْ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَالشَّمْسِ وَضُحَاهَا ‏ ‏وَنَحْوِهِمَا ‏","","",""],[11800,11800,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏وَاصَلَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آخِرَ الشَّهْرِ ‏ ‏وَوَاصَلَ ‏ ‏نَاسٌ مِنْ النَّاسِ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَوْ مُدَّ لَنَا الشَّهْرُ ‏ ‏لَوَاصَلْتُ ‏ ‏وِصَالًا ‏ ‏يَدَعُ ‏ ‏الْمُتَعَمِّقُونَ ‏ ‏تَعَمُّقَهُمْ ‏ ‏إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَظَلُّ يُطْعِمُنِي رَبِّي وَيَسْقِينِي ‏","","",""]];
